// Generated by Ember from its command registry. Ember rewrites this file each
// time it starts, so edit init.ts rather than this file.
//
// It declares the `ember` global for every .ts file. Each file is a module of
// its own (tsconfig.json sets moduleDetection to force), as Ember runs each
// file in its own scope.

export {};

declare global {
  namespace ember {
    /** Every command, with the arguments it takes in order. */
    interface Commands {
      /**
       * Move point backward a character, or as many as the prefix argument says.
       *
       * A negative argument moves forward.
       */
      "backward-char": [];
      /**
       * Kill back to the start of a word, or as many words as the prefix argument says.
       *
       * A negative argument kills forward.
       */
      "backward-kill-word": [];
      /**
       * Move point back to the start of a word, or as many words as the prefix argument says.
       *
       * A negative argument moves forward.
       */
      "backward-word": [];
      /**
       * Move point to the beginning of the buffer.
       *
       * Unless the region is active, leaves the mark where point was. With a numeric prefix argument N, move to N tenths of the way through the buffer instead, at the start of the next line. Plain C-u does not leave the mark.
       */
      "beginning-of-buffer": [];
      /**
       * Delete the character before point, or as many as the prefix argument says.
       *
       * With a prefix argument, the characters are killed rather than deleted, so they can be yanked back.
       */
      "delete-backward-char": [];
      /**
       * Delete the character after point, or as many as the prefix argument says.
       *
       * With a prefix argument, the characters are killed rather than deleted, so they can be yanked back.
       */
      "delete-char": [];
      /**
       * List all key bindings.
       */
      "describe-bindings": [];
      /**
       * Show the documentation of a command.
       *
       * @param command command name
       */
      "describe-command": [command: string];
      /**
       * Show which command a key sequence runs.
       *
       * @param key key sequence
       */
      "describe-key": [key: string];
      /**
       * Add the digit typed to the prefix argument, as M-5 or the digits after C-u do.
       *
       * Defined in packages/simple.ts.
       */
      "digit-argument": [];
      /**
       * Move point to the end of the buffer.
       *
       * Unless the region is active, leaves the mark where point was. With a numeric prefix argument N, move to N tenths of the way from the end instead, at the start of the next line. Plain C-u does not leave the mark.
       */
      "end-of-buffer": [];
      /**
       * Evaluate a TypeScript expression and show its value.
       *
       * The `ember` API is available, as in init.ts.
       *
       * @param expression text
       */
      "eval-expression": [expression: string];
      /**
       * Put the mark where point is and point where the mark was.
       */
      "exchange-point-and-mark": [];
      /**
       * Read a command name, with completion, and run it.
       *
       * A prefix argument given to M-x goes to the command it runs.
       *
       * @param command command name
       */
      "execute-extended-command": [command: string];
      /**
       * Finish the minibuffer input and pass it to the waiting command.
       */
      "exit-minibuffer": [];
      /**
       * Visit a file in a buffer.
       *
       * A file that does not exist yet is created when the buffer is saved.
       *
       * @param file file name
       */
      "find-file": [file: string];
      /**
       * Move point forward a character, or as many as the prefix argument says.
       *
       * A negative argument moves backward.
       */
      "forward-char": [];
      /**
       * Move point forward to the end of a word, or as many words as the prefix argument says.
       *
       * A negative argument moves backward.
       */
      "forward-word": [];
      /**
       * Indent the current line. For now this inserts a tab.
       */
      "indent-for-tab-command": [];
      /**
       * Insert text at point.
       *
       * @param text text
       */
      "insert": [text: string];
      /**
       * Cancel the current prompt or key sequence, and deactivate the region.
       */
      "keyboard-quit": [];
      /**
       * Close a buffer. Empty input closes the current one.
       *
       * Refuses to close a file buffer with unsaved changes.
       *
       * @param buffer buffer name
       */
      "kill-buffer": [buffer: string];
      /**
       * Kill the rest of the line, or the newline if only spaces and tabs are left.
       *
       * With a prefix argument N, kill N whole lines, newlines included; 0 kills back to the start of the line, and a negative N kills lines backward. Consecutive kills join into one kill ring entry.
       */
      "kill-line": [];
      /**
       * Kill the text between point and the mark.
       */
      "kill-region": [];
      /**
       * Copy the text between point and the mark to the kill ring.
       */
      "kill-ring-save": [];
      /**
       * Kill forward to the end of a word, or as many words as the prefix argument says.
       *
       * A negative argument kills backward.
       */
      "kill-word": [];
      /**
       * Run a TypeScript file, such as init.ts after editing it.
       *
       * Commands it defines replace existing commands with the same name.
       *
       * @param file file name
       */
      "load-file": [file: string];
      /**
       * Put point at the beginning of the buffer and the mark at the end.
       */
      "mark-whole-buffer": [];
      /**
       * Complete the minibuffer input as far as it is unambiguous.
       */
      "minibuffer-complete": [];
      /**
       * Move point to the beginning of the line.
       *
       * With a prefix argument N, move forward N - 1 lines first.
       */
      "move-beginning-of-line": [];
      /**
       * Move point to the end of the line.
       *
       * With a prefix argument N, move forward N - 1 lines first.
       */
      "move-end-of-line": [];
      /**
       * Scroll the window for the mouse wheel or a trackpad.
       *
       * Scrolls by as many lines as the wheel event carries. Point stays where it is unless it would leave the window.
       */
      "mwheel-scroll": [];
      /**
       * Make the prefix argument negative, as C-- or M-- does.
       *
       * Defined in packages/simple.ts.
       */
      "negative-argument": [];
      /**
       * Insert a newline, or as many as the prefix argument says.
       */
      "newline": [];
      /**
       * Move point down a line, or as many as the prefix argument says.
       *
       * Repeated line moves keep to the column where they started.
       */
      "next-line": [];
      /**
       * Move point up a line, or as many as the prefix argument says.
       *
       * Repeated line moves keep to the column where they started.
       */
      "previous-line": [];
      /**
       * Scroll so the line with point is in the middle of the window.
       *
       * With a numeric prefix argument N, put it on line N of the window instead, counting from the bottom if N is negative.
       */
      "recenter": [];
      /**
       * Save the current buffer to its file.
       */
      "save-buffer": [];
      /**
       * Quit the editor.
       *
       * If file buffers have unsaved changes, asks you to repeat the command to quit anyway.
       */
      "save-buffers-kill-terminal": [];
      /**
       * Scroll the text down by nearly a screen, showing earlier lines.
       *
       * With a numeric prefix argument, scroll that many lines; with C-- alone, scroll the other way.
       */
      "scroll-down-command": [];
      /**
       * Scroll the text down a line, or as many as the prefix argument says.
       */
      "scroll-down-line": [];
      /**
       * Scroll the text up by nearly a screen, showing later lines.
       *
       * With a numeric prefix argument, scroll that many lines; with C-- alone, scroll the other way.
       */
      "scroll-up-command": [];
      /**
       * Scroll the text up a line, or as many as the prefix argument says.
       */
      "scroll-up-line": [];
      /**
       * Insert the character you typed, as many times as the prefix argument says.
       */
      "self-insert-command": [];
      /**
       * Set the mark at point and activate the region.
       *
       * Repeating it straight away deactivates the region, leaving the mark set.
       */
      "set-mark-command": [];
      /**
       * Show a buffer in the window, creating it if it does not exist.
       *
       * Empty input switches to the buffer shown before this one.
       *
       * @param buffer buffer name
       */
      "switch-to-buffer": [buffer: string];
      /**
       * Undo the last change, or as many changes as the prefix argument says.
       *
       * Repeat to undo earlier changes.
       */
      "undo": [];
      /**
       * Begin a prefix argument for the next command.
       *
       * Digits or a minus sign typed after it make the argument; without them it is 4, and each further C-u multiplies it by 4. Most commands repeat that many times.
       *
       * Defined in packages/simple.ts.
       */
      "universal-argument": [];
      /**
       * Multiply the prefix argument by 4, as a second C-u does.
       *
       * After digits, it ends the argument instead, so digits typed after it are inserted.
       *
       * Defined in packages/simple.ts.
       */
      "universal-argument-more": [];
      /**
       * Write the current buffer to a file and visit that file.
       *
       * @param file file name
       */
      "write-file": [file: string];
      /**
       * Insert the most recent kill, leaving the mark at its start.
       *
       * With a numeric prefix argument N, insert the Nth most recent kill. With plain C-u, leave point at the start and the mark at the end.
       */
      "yank": [];
    }

    type CommandName = keyof Commands;

    const definedCommand: unique symbol;
    /** The name of a command defined by a script, as returned by defineCommand. */
    type DefinedCommand = string & { readonly [definedCommand]: true };

    /** How the minibuffer reads a parameter when the command runs from a key or M-x. */
    type ParamKind = "string" | "file" | "buffer" | "command" | "keys";

    interface Param {
      name: string;
      /** Defaults to "string". A "keys" parameter is passed in Emacs notation, such as "C-x C-f". */
      kind?: ParamKind;
      /** The minibuffer prompt. Defaults to the name followed by ": ". */
      prompt?: string;
    }

    interface CommandDefinition {
      /** Lowercase words joined by dashes, as in Emacs: "insert-date". */
      name: string;
      /** The first line is a one-line summary. Shown by describe-command (C-h f). */
      doc?: string;
      /** Read from the minibuffer, in order, when the command runs from a key or M-x. */
      params?: Param[];
      /** Receives one string per parameter. Throw an Error to fail with its message. */
      run: (...args: string[]) => void;
    }

    /**
     * Define a command, or replace the command with the same name.
     * Returns the name, which bindKey and call accept before this file is regenerated.
     */
    function defineCommand(definition: CommandDefinition): DefinedCommand;
    /** Bind a key sequence in Emacs notation, such as "C-c d", to a command. */
    function bindKey(keys: string, command: CommandName | DefinedCommand): void;
    /** Run a command with its arguments. Throws if the command fails. */
    function call<N extends CommandName | DefinedCommand>(
      name: N,
      ...args: N extends CommandName ? Commands[N] : string[]
    ): void;
    /** Show a message in the echo area. */
    function message(text: string): void;
    /** Insert text at point in the current buffer, leaving point after it. */
    function insert(text: string): void;
    /** Point, as a character offset from the start of the buffer, counting from 0. */
    function point(): number;
    /** Move point to a character offset. */
    function gotoChar(position: number): void;
    /** The text of the current buffer, or of the range from start up to end. */
    function bufferText(start?: number, end?: number): string;
    /** Delete the text from start up to end and return it. */
    function deleteRegion(start: number, end: number): string;
    /** The name of the current buffer. */
    function bufferName(): string;
    /** The mark, or undefined if it is not set. */
    function mark(): number | undefined;

    /**
     * A prefix argument, in the forms Emacs uses: null when none was given, a
     * number typed as digits (M-5, C-u 1 2), "-" for a minus sign alone (C--),
     * or a one-element array for plain C-u: [4], or [16] for C-u C-u.
     */
    type PrefixArg = null | number | "-" | [number];
    /** The prefix argument the running command was given (Emacs's current-prefix-arg). */
    function prefixArg(): PrefixArg;
    /**
     * A prefix argument as a count, as Emacs's prefix-numeric-value gives it:
     * 1 for none, -1 for "-", and n for n or [n]. Defaults to the running
     * command's argument.
     */
    function prefixNumericValue(arg?: PrefixArg): number;
    /**
     * Give the next command a prefix argument, as C-u does (Emacs's prefix-arg).
     * A command that leaves one does not count as the last command.
     */
    function setPrefixArg(arg: PrefixArg): void;
    /** The key that ran the current command, in Emacs notation such as "M-5" (Emacs's last-command-event). */
    function lastKey(): string | undefined;
    /**
     * Bind keys for the next key sequence only, ahead of every other keymap
     * (Emacs's set-transient-map). Prefix commands use it so that more digits
     * continue the argument.
     */
    function setTransientMap(bindings: { [keys: string]: CommandName | DefinedCommand }): void;
  }

  var console: {
    /** Show values in the echo area, separated by spaces. */
    log(...values: unknown[]): void;
  };
}
